/**
 * Stands in for `$env/dynamic/private` under Vitest.
 *
 * That module is generated by SvelteKit during a build, so a plain Vitest run
 * cannot resolve it and any test importing a server module that reads env
 * fails to collect. `vitest.config.ts` aliases it here.
 *
 * SvelteKit's dynamic private env is `process.env` at runtime, so this is the
 * same object the real module would hand back rather than a fake.
 */
export const env = process.env;
